import fs from "node:fs";
const txt = fs.readFileSync(process.argv[2], "utf8");
const re = /^(lib\/[^\s(]+)\((\d+),(\d+)\): error (TS\d+): (.*)$/gm;
const cache = {};
let m; const out = [];
