import fs from "node:fs";
import path from "node:path";
import ts from "typescript";

const root = process.cwd();
const config = ts.getParsedCommandLineOfConfigFile(path.resolve("tsconfig.indexed.json"), {}, { ...ts.sys, onUnRecoverableConfigFileDiagnostic() {} });
const program = ts.createProgram({ rootNames: config.fileNames, options: config.options });
const checker = program.getTypeChecker();
const testFiles = config.fileNames.filter(f => /lib[\\/]finance[\\/].*\.test\.ts$/.test(f));
const handledCodes = new Set([2532, 2322, 2345, 18048]);
let changed = 0;

function hasUndefined(node) {
  const type = checker.getTypeAtLocation(node);
  const parts = type.isUnion() ? type.types : [type];
  return parts.some(p => p.flags & ts.TypeFlags.Undefined);
}

for (const file of testFiles) {
  const sf = program.getSourceFile(file);
  const diags = ts.getPreEmitDiagnostics(program, sf).filter(d => d.file === sf && handledCodes.has(d.code));
  const wraps = new Map();
  const bangs = [];
  function visit(node) {
    if (ts.isNonNullExpression(node)) bangs.push(node);
    ts.forEachChild(node, visit);
  }
  visit(sf);
  for (const d of diags) {
    const start = d.start, end = d.start + d.length;
    function find(node) {
      if (node.getEnd() < start || node.getStart(sf) > end) return;
      if (ts.isElementAccessExpression(node) && node.getStart(sf) >= start && node.getEnd() <= end && hasUndefined(node)) {
        wraps.set(`${node.getStart(sf)}:${node.getEnd()}`, node);
      }
      ts.forEachChild(node, find);
    }
    find(sf);
    if (d.code === 2532) {
      let n = sf;
      (function f(node) {
        if (node.getStart(sf) === start && node.getEnd() === end) n = node;
        if (node.getStart(sf) <= start && node.getEnd() >= end) ts.forEachChild(node, f);
      })(sf);
      if (n !== sf && !ts.isElementAccessExpression(n)) wraps.set(`${n.getStart(sf)}:${n.getEnd()}`, n);
    }
  }
  const edits = [];
  for (const n of wraps.values()) {
    edits.push({ pos: n.getStart(sf), del: 0, text: "defined(" });
    edits.push({ pos: n.getEnd(), del: 0, text: ")" });
  }
  for (const b of bangs) {
    edits.push({ pos: b.expression.getStart(sf), del: 0, text: "defined(" });
    edits.push({ pos: b.getEnd() - 1, del: 1, text: ")" });
  }
  if (!edits.length) continue;
  let text = sf.text;
  edits.sort((a, b) => b.pos - a.pos || (a.text === ")" ? -1 : 1));
  for (const e of edits) text = text.slice(0, e.pos) + e.text + text.slice(e.pos + e.del);
  if (!/import \{[^}]*\bdefined\b[^}]*\} from "@\/lib\/testing"/.test(text)) {
    const lines = text.split("\n");
    let last = -1;
    lines.forEach((l, i) => { if (/^import .* from ".*";\s*$/.test(l) || /^\} from ".*";\s*$/.test(l)) last = i; });
    lines.splice(last + 1, 0, 'import { defined } from "@/lib/testing";');
    text = lines.join("\n");
  }
  fs.writeFileSync(file, text);
  changed++;
  console.log(path.relative(root, file), wraps.size, bangs.length);
}
console.log("files", changed);
EOF
cp "$SP/codemod.mjs" ./codemod.tmp.mjs && node codemod.tmp.mjs | tail -60; rm codemod.tmp.mjs

