const fs=require("fs");let t=fs.readFileSync("AGENTS.md","utf8");
const a="(so far `lib/bank` and the non-test files of `lib/finance`; the `lib/finance` tests are next, by removing their entry from `exclude`). To migrate the next folder: add `<folder>/**/*.ts` to `include` there (list its tests under `exclude` if they are left for a second step)";
if(!t.includes(a))throw 1;
t=t.replace(a,"(so far `lib/bank` and `lib/finance`, tests included). To migrate the next folder: add `<folder>/**/*.ts` to `include` there (list its tests under `exclude` if they are left for a second step)");
fs.writeFileSync("AGENTS.md",t);
EOF
git add lib/finance/*.live.test.ts && git commit -q -m "Check indexed access in the lib/finance database tests

Rows read from the database and first elements are now narrowed with defined() instead of being assumed present.

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>" && git add lib && git commit -q -m "Check indexed access in the lib/finance unit tests

